#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include "../src/dsp.h"
int main(void){int cases=0;for(int bits=16;bits<=32;bits+=8)for(int rate=44100;rate<=96000;rate+=(rate==44100?3900:48000))for(int channels=1;channels<=2;channels++)for(int gain=-12;gain<=6;gain+=18){int frames=rate/3,bytes=frames*channels*(bits/8);unsigned char *p=malloc(bytes+16);memset(p+bytes,0xA5,16);for(int f=0;f<frames;f++)for(int ch=0;ch<channels;ch++)encode(p+(f*channels+ch)*(bits/8),bits,ch==0?.1*sin(2*PI*1000*f/rate):0);Config c;defaults(&c);c.bands[5].gain=gain;c.bands[5].q=20;Engine e={0};for(int f=0;f<frames;f+=137)process(&e,&c,p+f*channels*(bits/8),frames-f<137?frames-f:137,bits,channels,rate);double energy=0;int n=0;for(int f=rate/5;f<frames;f++){double y=decode(p+f*channels*(bits/8),bits)/ldexp(1,bits-1);energy+=y*y;n++;if(channels==2)assert(decode(p+(f*2+1)*(bits/8),bits)==0);}double db=20*log10(sqrt(energy/n)/(.1/sqrt(2)));assert(fabs(db-gain)<.08);for(int i=0;i<16;i++)assert(p[bytes+i]==0xA5);free(p);cases++;}Config c;defaults(&c);c.preamp=-12;int32_t sample=1073741824;Engine e={0};process(&e,&c,&sample,1,32,1,48000);assert(fabs(sample/2147483648.-.5*pow(10,-12/20))<1e-8);c.enabled=0;c.generation++;Engine d={0};unsigned char data[32],copy[32];for(int i=0;i<32;i++)copy[i]=data[i]=(i*137+37)&255;process(&d,&c,data,8,32,1,48000);assert(!memcmp(data,copy,32));printf("PASS: %d PCM filter response cases, channel isolation, buffer canaries, first-sample preamp and exact disabled bypass\n",cases);return 0;}
